# Generated by build.py from recipe.yml for recipe curl-write-a-test-report-with-write-out. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/health.txt'), "ok`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/version.txt'), "1.4.2`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -o NUL -w "%output{>>report.jsonl}%{json}\n" "http://127.0.0.1:8080/{health,version,missing}.txt" } finally { Stop-Process $server0 }
